{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"Rent may be increased only once every 12 months at the allowable rent increase percentage. Since February 2, 2026 a landlord may not add a utility percentage increase or a 10% increase for an additional dependent; 10% for an additional tenant is allowed.","key_value":"Once every 12 months at the allowable rent increase percentage","coverage_conditions":"Rental properties first built on or before October 1, 1978, plus replacement units under LAMC §151.28, including apartments, condominiums, townhomes, duplexes, two or more single-family units on one parcel, ADUs and mobile homes.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Replacement units under LAMC §151.28; condominium and townhome rent not regulated for tenancies commencing after December 31, 1995"},"exemptions":"Units built after October 1, 1978; condominium and townhome units with tenancies beginning after December 31, 1995; Luxury Exemption for units renting at the qualifying level on or before May 31, 1978; temporary exemptions.","penalty":null,"effective_date":"2026-02-02","citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and relocation assistance","requirement":"Under the RSO a landlord may end a tenancy only for the listed at-fault or no-fault reasons; no-fault evictions require payment of tenant relocation assistance, and every termination notice must be filed with LAHD within three business days of service.","key_value":"3 business days to file notice with LAHD; relocation assistance for no-fault evictions","coverage_conditions":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance, generally properties first built on or before October 1, 1978.","applicability":{"built_on_or_before":"1978-10-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Notice-filing rule cites LAMC 151.09.C.9 and 165.05.B.5"},"exemptions":"Units outside the RSO (for example those built after October 1, 1978) are instead subject to the City's Just Cause Ordinance.","penalty":null,"effective_date":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
